@code {
    [Parameter] public string? InitialData { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string CoverLetter = string.Empty;
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (InitialData is not null)
        {
            CoverLetter = InitialData;
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
}
