{"file_text": "@using sv_d3c510facab04b8c871dd287d16990c9.Models

<div class="review-step">
    <h4>Review & Submit</h4>
    <p class="text-muted">Please review your application before submitting.</p>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you soon.</p>
        </div>
    }
    else
    {
        <!-- Personal Info Section -->
        <div class="review-section">
            <div class="section-header">
                <h5>Personal Information</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="row">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@Personal?.FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@Personal?.Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@Personal?.Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@Personal?.Address</dd>
            </dl>
        </div>

        <!-- Work History Section -->
        <div class="review-section">
            <div class="section-header">
                <h5>Work History</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @if (WorkEntries is not null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="work-entry-review">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &mdash;
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <!-- References Section -->
        <div class="review-section">
            <div class="section-header">
                <h5>References</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="reference-review">
                        <strong>@r.Name</strong> — @r.Relationship<br />
                        <small>@r.Email @(string.IsNullOrWhiteSpace(r.Phone) ? "" : $"| {r.Phone}")</small>
                    </div>
                }
            }
        </div>

        <!-- Cover Letter Section -->
        <div class="review-section">
            <div class="section-header">
                <h5>Cover Letter</h5>
                <button type="button" class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="d-flex justify-content-between mt-4">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;

        try
        {
            var application = new JobApplication(
                Personal!,
                new WorkHistory(WorkEntries!),
                References!,
                CoverLetter!
            );

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
            await OnSubmitted.InvokeAsync(ApplicationId);
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Failed to submit application: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}
